#include "MeshMapsPanel.hh"
#include <QHeaderView>
#include <QLabel>
#include <QPushButton>
#include <QToolButton>
#include <QTreeWidget>
#include <QVBoxLayout>
namespace bts {
MeshMapsPanel::MeshMapsPanel(QWidget *parent):QWidget(parent){setObjectName("meshMapsPanel");auto *layout=new QVBoxLayout(this);layout->setContentsMargins(0,4,0,0);layout->addWidget(new QLabel("MESH MAPS",this));bake_=new QPushButton("Bake Mesh Maps…",this);bake_->setObjectName("bakeMeshMaps");layout->addWidget(bake_);connect(bake_,&QPushButton::clicked,this,[this]{if(bake)bake();});maps_=new QTreeWidget(this);maps_->setObjectName("meshMapResources");maps_->setColumnCount(3);maps_->setHeaderHidden(true);maps_->setRootIsDecorated(false);maps_->setIconSize({36,36});maps_->setMinimumHeight(160);maps_->header()->setSectionResizeMode(0,QHeaderView::ResizeToContents);maps_->header()->setSectionResizeMode(1,QHeaderView::Stretch);maps_->header()->setSectionResizeMode(2,QHeaderView::Fixed);maps_->setColumnWidth(2,24);layout->addWidget(maps_);connect(maps_,&QTreeWidget::itemDoubleClicked,this,[this](QTreeWidgetItem *item,int){if(item->data(0,Qt::UserRole+1).toBool()&&inspect)inspect(item->data(0,Qt::UserRole).toInt());});}
void MeshMapsPanel::synchronize(const TextureSet *set){bake_->setEnabled(set&&set->uniform_editable);QString key=set?set->id.toString():QString("none");if(set)for(const auto &map:set->mesh_maps){if(map)for(const auto &[tile,plane]:map->tiles)key+=QString::number(tile)+QString::fromStdString(plane.hash);}if(key==signature_)return;signature_=key;maps_->clear();for(int role=0;role<7;++role){const auto *map=set&&set->mesh_maps[role]?&*set->mesh_maps[role]:nullptr;auto *item=new QTreeWidgetItem(maps_,{QString::fromLatin1(mesh_map_names[role]),map?QString::fromStdString(map->name):"Not assigned"});item->setData(0,Qt::UserRole,role);item->setData(0,Qt::UserRole+1,bool(map));item->setToolTip(1,map?QString("%1 — %2/%3 UV tiles").arg(item->text(1)).arg(map->tiles.size()).arg(set->tiles.size()):item->text(1));item->setSizeHint(0,{0,42});if(map&&!map->tiles.empty()&&map->tiles.begin()->second.pixels){const auto &data=*map->tiles.begin()->second.pixels;QImage image(36,36,QImage::Format_RGB32);for(int y=0;y<36;++y)for(int x=0;x<36;++x){const auto i=(std::size_t((35-y)*data.height/36)*data.resolution+x*data.resolution/36)*4;image.setPixel(x,y,qRgb(qRound(255*std::clamp(data.rgba[i],0.f,1.f)),qRound(255*std::clamp(data.rgba[i+1],0.f,1.f)),qRound(255*std::clamp(data.rgba[i+2],0.f,1.f))));}item->setIcon(0,QPixmap::fromImage(image));}auto *button=new QToolButton(maps_);button->setText("×");button->setEnabled(map);button->setToolTip("Remove mesh map");maps_->setItemWidget(item,2,button);connect(button,&QToolButton::clicked,this,[this,role]{if(remove)remove(role);});}}
}
